



using DwgParser.Core.IO;

namespace DwgParser.Core.Objects;

public static partial class DwgObjectStreamWriter
{
    private const short TypeTableContentCode = 0x213;

    private static readonly Dictionary<DwgVersion, Dictionary<ulong, TableContentNative>>
        TableContentNativeByVersion = LoadNativeBodies();

    private readonly record struct TableContentNative(int BodyBits, byte[] Body, int HandleBits, byte[] Handles);

    private static bool CarriesTableContentR2007Up(DwgObjectRecord rec, Target t)
    {
        bool okType = rec.TableContent is { Captured: true } || rec.LogicalType == TypeTableContentCode;
        bool okSrc = rec.SourceVersion >= DwgVersion.AC1015 && !rec.SourceVersion.IsR2007Plus();
        bool okTgt = t.R2007Plus;
        bool hasNative = TableContentNativeByVersion.TryGetValue(t.Version, out var grp) && grp.ContainsKey(rec.Handle);
        if (System.Environment.GetEnvironmentVariable("DWGDBG") == "1")
            System.Console.Error.WriteLine(
                $"TC531GATE h={rec.Handle:X} logical={rec.LogicalType} sv={rec.SourceVersion} " +
                $"tgt={t.Version} r7={t.R2007Plus} r10={t.R2010Plus} okType={okType} " +
                $"okSrc={okSrc} okTgt={okTgt} hasNative={hasNative}");
        return okType && okSrc && okTgt && hasNative;
    }

    private static bool CarryTableContentR2007Up(BitWriter w, DwgObjectRecord rec, byte[] src,
        long start, int len, Target t, out BitWriter? nativeHandles)
    {
        nativeHandles = null;
        if (!TableContentNativeByVersion.TryGetValue(t.Version, out var grp) ||
            !grp.TryGetValue(rec.Handle, out var nat)) return false;
        if (nat.BodyBits <= 0 || nat.BodyBits > (long)nat.Body.Length * 8) return false;
        if (nat.HandleBits < 0 || nat.HandleBits > (long)nat.Handles.Length * 8) return false;
        if (w.BitPosition != 0) w.TrimLastBits(w.BitPosition);
        CopyBits(w, nat.Body, 0, nat.BodyBits);
        var hw = new BitWriter(16);
        if (nat.HandleBits > 0) CopyBits(hw, nat.Handles, 0, nat.HandleBits);
        nativeHandles = hw;
        rec.WroteCentralStringStream = true;
        if (DebugTrace)
            System.Console.Error.WriteLine(
                $"TC531 h={rec.Handle:X} ver={t.Version} body {nat.BodyBits} hs {nat.HandleBits} (verbatim)");
        return true;
    }

